<?php
function ePubDev(string $v): string { return htmlspecialchars($v, ENT_QUOTES, 'UTF-8'); }
function moneyPubDev(float $v): string { return 'R$ '.number_format($v,2,',','.'); }
$voltar = (($usuario['tipo']??'')==='cliente') ? '/cliente/desenvolvedores.php' : '/desenvolvedor/dashboard.php';
?>
<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Perfil de desenvolvedor - SiteMatch</title><link rel="stylesheet" href="/css/global.css"><link rel="stylesheet" href="/css/dashboard.css"><link rel="stylesheet" href="/css/functional.css"></head><body><main class="dashboard-main" style="max-width:1050px;margin:0 auto;"><p style="margin-bottom:20px;"><a href="<?= ePubDev($voltar) ?>">← Voltar</a></p><header class="dashboard-header"><div class="dashboard-header-text"><h1><?= ePubDev((string)$perfilPublico['nome']) ?></h1><p><?= ePubDev((string)($perfilPublico['titulo_profissional']?:'Desenvolvedor')) ?></p></div><?php if((int)$perfilPublico['total_avaliacoes']>0): ?><span class="projeto-status">★ <?= ePubDev((string)$perfilPublico['media_avaliacoes']) ?> · <?= (int)$perfilPublico['total_avaliacoes'] ?> avaliação(ões)</span><?php endif; ?></header>
<section class="dashboard-section"><div class="form-card"><h2>Perfil profissional</h2><p style="line-height:1.6;"><?= nl2br(ePubDev((string)($perfilPublico['bio']??'Descrição não informada.'))) ?></p><?php if(!empty($perfilPublico['experiencia'])): ?><h3 style="margin-top:20px;">Experiência</h3><p style="margin-top:8px;line-height:1.6;"><?= nl2br(ePubDev((string)$perfilPublico['experiencia'])) ?></p><?php endif; ?><div class="projeto-meta" style="margin-top:18px;"><span>Disponibilidade: <strong><?= ePubDev((string)($perfilPublico['disponibilidade']??'Não informada')) ?></strong></span><?php if($perfilPublico['faixa_preco_min']!==null): ?><span>Faixa: <strong><?= moneyPubDev((float)$perfilPublico['faixa_preco_min']) ?><?= $perfilPublico['faixa_preco_max']!==null?' a '.moneyPubDev((float)$perfilPublico['faixa_preco_max']):'' ?></strong></span><?php endif; ?></div><?php if(!empty($perfilPublico['habilidades_lista'])): ?><div class="tags"><?php foreach($perfilPublico['habilidades_lista'] as $h): ?><span class="tag"><?= ePubDev((string)$h['nome']) ?> · <?= ePubDev((string)$h['nivel']) ?></span><?php endforeach; ?></div><?php endif; ?></div></section>
<section class="dashboard-section"><h2>Portfólio</h2><?php if(empty($perfilPublico['portfolio'])): ?><div class="projetos-vazio">Nenhum trabalho publicado.</div><?php else: ?><div class="lista-simples"><?php foreach($perfilPublico['portfolio'] as $item): ?><article class="projeto-card"><h3><?= ePubDev((string)$item['titulo']) ?></h3><p style="margin-top:8px;line-height:1.5;"><?= ePubDev((string)$item['descricao']) ?></p><div class="acoes-inline"><?php if(!empty($item['link_projeto'])): ?><a class="botao-secundario" target="_blank" rel="noopener" href="<?= ePubDev((string)$item['link_projeto']) ?>">Projeto</a><?php endif; ?><?php if(!empty($item['link_repositorio'])): ?><a class="botao-secundario" target="_blank" rel="noopener" href="<?= ePubDev((string)$item['link_repositorio']) ?>">Repositório</a><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?></section>
<section class="dashboard-section"><h2>Avaliações</h2><?php if(empty($perfilPublico['avaliacoes'])): ?><div class="projetos-vazio">Este desenvolvedor ainda não possui avaliações.</div><?php else: ?><div class="lista-simples"><?php foreach($perfilPublico['avaliacoes'] as $a): ?><article class="projeto-card"><strong>★ <?= (int)$a['nota'] ?>/5 · <?= ePubDev((string)$a['projeto_titulo']) ?></strong><p style="margin-top:8px;"><?= ePubDev((string)($a['comentario']??'')) ?></p></article><?php endforeach; ?></div><?php endif; ?></section>
</main></body></html>
